insert into public.product_images (product_id, storage_path, alt_de)
select id, primary_image_url, name_de || ' – Produktabbildung'
from public.products
where primary_image_url is not null
on conflict (product_id, storage_path) do nothing;

insert into public.inventory (product_id, location_id, available_qty, pickup_available, delivery_available, lead_time_de)
select p.id, l.id,
  case when l.slug = 'berlin-mitte' then 12 + (row_number() over (order by p.id) * 7)::integer % 130 else 50 + (row_number() over (order by p.id) * 23)::integer % 500 end,
  l.slug = 'berlin-mitte', true,
  case when l.slug = 'berlin-mitte' then 'Abholbereit in 2 Stunden' else 'Lieferbar in 2–4 Werktagen' end
from public.products p cross join public.locations l
on conflict (product_id, location_id) do update set available_qty = excluded.available_qty;

insert into public.product_variant_links (product_id, sibling_product_id, label_de)
select a.id, b.id, b.variant_label
from public.products a
join public.products b on a.variant_group = b.variant_group and a.id <> b.id
where a.variant_group is not null
on conflict do nothing;
